<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Settings,SettingsSchema,MembershipApplications,AdmissionVotes,Finance,MembershipWelcome,ContributionInvoices,DocumentCatalog,Permissions};
$n=0;function ok(bool $value,string $label):void{global $n;if(!$value)throw new RuntimeException($label);$n++;echo "PASS $label\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException){ok(true,$label);return;}throw new RuntimeException($label);}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Synthetic Club'); INSERT INTO actors(id,club_id,role,is_superuser) VALUES('manager','a','members',1),('clerk','a','member',0); INSERT INTO actor_capabilities VALUES('manager','local_finance');");
(new AdmissionVotes($db,'manager'))->grant('clerk',0,'Schriftführer',true,true);
$settings=new Settings($db,'manager');$company=SettingsSchema::defaults('club');$company=array_replace($company,['name'=>'Synthetischer Testverein e. V.','street'=>'Testweg 99','postcode'=>'00000','city'=>'Testort']);$settings->save('club',$company,0);
$bank=SettingsSchema::defaults('bank');$bank=array_replace($bank,['account_id'=>(new Finance($db,'manager'))->createAccount('Invoice bank','offline','0','2026-01-01'),'holder'=>'Synthetischer Testverein','iban'=>'DE89370400440532013000','bic'=>'COBADEFFXXX']);$settings->save('bank',$bank,0);
$manager=new MembershipApplications($db,'a','manager');$intake=new MembershipApplications($db,'a','clerk');$config=$manager->settings()['config'];$config['enabled']=true;$manager->saveSettings($config,0);
$base=['first_name'=>'Synthetic','last_name'=>'Member','birthday'=>'1990-01-02','email'=>'one@example.invalid','address'=>"Testpfad 1\n00000 Testort",'membership_type'=>'single'];
$submit=static fn(array $data):string=>$intake->submit($data,bin2hex(random_bytes(16)),1,true);
$accept=static fn(string $id,string $family='single'):?string=>$intake->review($id,1,'accepted','Synthetic board decision',start:date('Y-m-d'),externalDecision:true,decisionDate:date('Y-m-d'),familyTarget:$family);
$id=$submit($base);$contact=$accept($id);
$welcome=static fn(string $application):array=>DocumentCatalog::query($db,'SELECT * FROM membership_welcome WHERE application_id=?',[$application])->fetch();
$row=$welcome($id);$entry=DocumentCatalog::raw($db,'a','entry',$row['entry_id']);$invoice=DocumentCatalog::query($db,'SELECT * FROM contribution_invoices WHERE entry_id=?',[$row['entry_id']])->fetch();
ok($entry['kind']==='contribution'&&(int)$entry['amount_cents']===4800,'acceptance creates one actual 48 EUR contribution');
ok($entry['due_date']===Finance::contributionDueDate($entry['document_date']),'new membership gets one calendar month payment term');
foreach(['2026-01-31'=>'2026-02-28','2024-01-31'=>'2024-02-29','2026-12-31'=>'2027-01-31','2026-05-15'=>'2026-06-15'] as $start=>$end)ok(Finance::contributionDueDate($start)===$end,'calendar month clamp '.$start);
ok($invoice['state']==='issued'&&$invoice['recipient_contact_id']===$contact,'invoice uses actual accepted payer');
$file=DocumentCatalog::query($db,'SELECT * FROM document_files WHERE document_id=? ORDER BY revision DESC LIMIT 1',[$invoice['document_id']])->fetch();$snapshot=json_decode($file['snapshot'],true);
ok(str_starts_with($file['bytes'],'%PDF-')&&$snapshot['kind']==='invoice'&&!$snapshot['draft']&&str_starts_with($snapshot['recipient'],'Synthetic Member'),'real invoice PDF has actual recipient, not preview data');
ok($snapshot['values']['RECHNUNGSNUMMER']===$entry['display_number']&&$snapshot['values']['FAELLIGKEIT']===date('d.m.Y',strtotime($entry['due_date'])),'invoice preserves finance number and due date');
if(getenv('VEREIN_TEST_INVOICE_OUTPUT'))file_put_contents(getenv('VEREIN_TEST_INVOICE_OUTPUT'),$file['bytes']);
ok(Permissions::actor($db,'clerk')['finance_access']==='none','admission automation grants reviewer no general finance permission');
denied(fn()=>(new Finance($db,'clerk'))->createEntry([],str_repeat('a',32)),'board clerk still cannot create arbitrary finance entries');
$before=(int)$db->query('SELECT COUNT(*) FROM document_files')->fetchColumn();$again=(new ContributionInvoices($db,'manager'))->issue($row['entry_id']);
ok($again['document_id']===$invoice['document_id']&&(int)$db->query('SELECT COUNT(*) FROM document_files')->fetchColumn()===$before,'issued invoice retry preserves exact document revision');
denied(fn()=>$accept($id),'repeated admission cannot duplicate charge or welcome');
ok((int)$db->query('SELECT COUNT(*) FROM finance_entries')->fetchColumn()===1&&(int)$db->query('SELECT COUNT(*) FROM membership_welcome')->fetchColumn()===1,'one charge and welcome per acceptance');
$messages=[];$accounts=[];$acks=[];
$send=static function($email,$subject,$text,$html,$attachments)use(&$messages):void{$messages[]=compact('email','subject','text','html','attachments');};
$provision=static function($application,$contact)use(&$accounts):array{$accounts[]=$application;return ['username'=>'synthetic-member','initial_password'=>'synthetic-start-password','password_change_required'=>true];};
$ack=static function($application)use(&$acks):void{$acks[]=$application;};
putenv('VEREIN_MODE=synthetic');ok(MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,$provision,$ack)===0&&!$messages&&!$accounts,'local mode blocks provisioning and mail dispatch');
foreach(['VEREIN_MODE','KULTURHUS_LOCAL_DEMO','KULTURHUS_DISABLE_MAIL','APP_ENV'] as $env)putenv($env);putenv('APP_URL=https://example.invalid');
ok(MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,$provision,$ack)===2,'fake welcome and separate invoice are dispatched in order');
ok(str_contains($messages[0]['text'],MembershipWelcome::INVOICE_NOTICE)&&$messages[0]['attachments']===[]&&count($messages[1]['attachments'])===1,'welcome announces separate invoice, invoice message carries PDF');
ok(str_contains($messages[0]['html'],'Zum Mitgliederbereich')&&str_contains($messages[0]['text'],'ersten Anmeldung')&&str_contains($messages[1]['html'],'Eure Beitragsrechnung')&&str_contains($messages[0]['text'],'/login/'),'account guidance and branded invoice mail present');
ok($messages[1]['attachments'][0]['bytes']===$file['bytes'],'mail attaches exact archived invoice');
ok(count($acks)===1&&!str_contains($welcome($id)['payload'],'synthetic-start-password'),'password escrow acknowledged only after mail and never persisted in welcome payload');
MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,$provision,$ack);ok(count($messages)===2&&count($accounts)===1,'repeated dispatcher never repeats confirmed messages');
$parentApp=$submit(array_replace($base,['last_name'=>'Family','email'=>'family@example.invalid','membership_type'=>'family']));$parent=$accept($parentApp,'new');
$family=DocumentCatalog::query($db,'SELECT f.* FROM member_families f WHERE payer_contact_id=?',[$parent])->fetch();
$childApp=$submit(array_replace($base,['first_name'=>'Child','last_name'=>'Family','birthday'=>'2018-01-02','email'=>'family@example.invalid','membership_type'=>'family_member','family_reference'=>'Synthetic Family']));$child=$accept($childApp,$family['id'].':'.$family['version']);
ok($welcome($childApp)['entry_id']===null&&$welcome($childApp)['invoice_status']==='skipped','family member gets no own invoice');
ok((int)$db->query('SELECT COUNT(*) FROM finance_entries')->fetchColumn()===2&&(int)$db->query('SELECT SUM(amount_cents) FROM finance_entries')->fetchColumn()===12000,'family creates only one 72 EUR contribution');
ok(DocumentCatalog::query($db,'SELECT entry_id FROM member_dues_people WHERE contact_id=?',[$child])->fetchColumn()===$welcome($parentApp)['entry_id'],'later family member is covered by existing family charge immediately');
$message=MembershipWelcome::message(json_decode($welcome($childApp)['payload'],true),['username'=>'child'],'https://example.invalid');ok(!str_contains($message['text'],MembershipWelcome::INVOICE_NOTICE),'family member welcome omits invoice announcement');
MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,$provision,$ack);
$uncertainApp=$submit(array_replace($base,['last_name'=>'Uncertain','email'=>'uncertain@example.invalid']));$accept($uncertainApp);$count=count($messages);$ackCount=count($acks);
MembershipWelcome::dispatch($db,'a','https://example.invalid',static function(){throw new RuntimeException('Unknown fake SMTP outcome');},$provision,$ack);
MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,$provision,$ack);
ok($welcome($uncertainApp)['welcome_status']==='uncertain'&&$welcome($uncertainApp)['invoice_status']==='waiting'&&count($messages)===$count&&count($acks)===$ackCount,'uncertain welcome is never resent, acknowledged or followed by invoice');
$accountApp=$submit(array_replace($base,['last_name'=>'Account','email'=>'account@example.invalid']));$accept($accountApp);
MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,static function(){throw new DomainException('Identity needs assignment');},$ack);
ok($welcome($accountApp)['welcome_status']==='needs_account'&&count($messages)===$count,'unresolved identity is held before any mail');
$settings->save('bank',array_replace($bank,['iban'=>'']),1);
$draftApp=$submit(array_replace($base,['last_name'=>'Draft','email'=>'draft@example.invalid']));$accept($draftApp);$draftRow=$welcome($draftApp);
$draft=DocumentCatalog::query($db,'SELECT * FROM contribution_invoices WHERE entry_id=?',[$draftRow['entry_id']])->fetch();ok($draft['state']==='draft'&&str_contains($draft['missing_fields'],'Bankverbindung'),'missing bank data produces marked draft instead of fabricated payment data');
MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,$provision,$ack);ok($welcome($draftApp)['welcome_status']==='sent'&&$welcome($draftApp)['invoice_status']==='waiting','incomplete invoice does not block welcome and cannot be sent');
$settings->save('bank',$bank,2);$ready=(new ContributionInvoices($db,'manager'))->issue($draftRow['entry_id']);
ok($ready['state']==='issued'&&$ready['document_id']===$draft['document_id'],'corrected settings finalize same invoice document');
MembershipWelcome::dispatch($db,'a','https://example.invalid',$send,$provision,$ack);ok($welcome($draftApp)['invoice_status']==='sent','finalized invoice can follow prior welcome');
ok(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok'&&\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)===[],'invoice, acceptance and document links retain integrity');
$visible=MembershipWelcome::status($db,'clerk',$draftApp);
ok($visible['invoice_status']==='sent'&&$visible['invoice_state']==='issued'&&$visible['missing_fields']===[],'board sees welcome and finalized invoice statuses');
ok(!isset($visible['payload'],$visible['email'],$visible['initial_password']),'board status contains no credentials or mail payload');
denied(fn()=>MembershipWelcome::status($db,'unknown',$id),'unknown actor cannot read welcome status');
$db->exec("INSERT INTO clubs VALUES('other','Synthetic Other');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('outsider','other','member',1)");
ok(MembershipWelcome::status($db,'outsider',$id)===null,'welcome status is tenant scoped');
ok(MembershipWelcome::status($db,'clerk',$childApp)['invoice_status']==='skipped','family nonpayer status has no invoice');
$separateApp=$submit(array_replace($base,['last_name'=>'Separate','email'=>'separate@example.invalid']));$accept($separateApp);
$welcomeOnly=[];$invoiceOnly=[];
$welcomeAdapter=static function(...$args)use(&$welcomeOnly){$welcomeOnly[]=$args;};$invoiceAdapter=static function(...$args)use(&$invoiceOnly){$invoiceOnly[]=$args;};
ok(MembershipWelcome::dispatch($db,'a','https://example.invalid',$welcomeAdapter,$provision,$ack,$invoiceAdapter)===2&&count($welcomeOnly)===1&&count($invoiceOnly)===1,'separate invoice adapter receives only first contribution invoice');
ok($welcomeOnly[0][4]===[]&&count($invoiceOnly[0][4])===1,'welcome remains on ordinary adapter and invoice keeps its archived attachment');
$brokenApp=$submit(array_replace($base,['last_name'=>'BrokenInvoice','email'=>'brokeninvoice@example.invalid']));$accept($brokenApp);
$beforeWelcome=count($welcomeOnly);
MembershipWelcome::dispatch($db,'a','https://example.invalid',$welcomeAdapter,$provision,$ack,static function(){throw new DomainException('Invoice adapter unavailable');});
ok(count($welcomeOnly)===$beforeWelcome+1&&$welcome($brokenApp)['welcome_status']==='sent'&&$welcome($brokenApp)['invoice_status']==='uncertain','broken invoice adapter neither blocks welcome nor falls back to ordinary delivery');
MembershipWelcome::dispatch($db,'a','https://example.invalid',$welcomeAdapter,$provision,$ack,$invoiceAdapter);
ok(count($invoiceOnly)===1,'uncertain invoice transport is not automatically replayed after repair');
echo "$n membership-welcome checks passed; synthetic data and fake callbacks only\n";
